import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

import { API_URL } from "../config";

function LoginPage({ setSession, session }) {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    username: "admin",
    password: "admin123",
    role: "ADMIN",
  });

  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  // =====================================================
  // REDIRECT IF ALREADY LOGGED IN
  // =====================================================

  useEffect(() => {
    if (session) {
      navigate("/");
    }
  }, [session, navigate]);

  // =====================================================
  // HANDLE INPUT CHANGE
  // =====================================================

  const handleChange = (event) => {
    const { name, value } = event.target;

    setForm((current) => ({
      ...current,
      [name]: value,
    }));
  };

  // =====================================================
  // LOGIN
  // =====================================================

  const handleSubmit = async (event) => {
    event.preventDefault();

    setLoading(true);
    setError("");

    try {
      const response = await fetch(
        `${API_URL}/auth/login`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(form),
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.message || "Login failed"
        );
      }

      // =================================================
      // CREATE SESSION
      // =================================================

      const nextSession = {
        token: data.token,
        userId: data.user._id,
        username: data.user.username,
        role: data.user.role,
        hospitalId:
          data.user.hospitalId || null,
        officeId:
          data.user.officeId || null,
      };

      setSession(nextSession);

      // =================================================
      // ROLE-BASED REDIRECT
      // =================================================

      if (data.user.role === "ADMIN") {
        navigate("/admin");
      } else if (
        data.user.role === "HOSPITAL"
      ) {
        navigate("/hospital-dashboard");
      } else if (
        data.user.role ===
        "GOVERNMENT OFFICE"
      ) {
        navigate("/office-dashboard");
      } else {
        navigate("/");
      }

    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // =====================================================
  // LOGIN UI
  // =====================================================

  return (
    <main className="min-h-screen bg-slate-50 px-6 py-12">

      <div className="mx-auto max-w-md rounded-3xl border border-slate-200 bg-white p-8 shadow-sm">

        <p className="text-sm font-semibold uppercase tracking-wider text-blue-700">
          Access Portal
        </p>

        <h1 className="mt-2 text-3xl font-bold text-slate-900">
          QueueLess India Login
        </h1>

        <p className="mt-2 text-sm text-slate-600">
          Use the demo admin account or create
          hospital/office accounts via backend.
        </p>

        <form
          onSubmit={handleSubmit}
          className="mt-6 space-y-4"
        >

          {/* USERNAME */}

          <div>
            <label className="mb-2 block text-sm font-semibold text-slate-700">
              Username
            </label>

            <input
              name="username"
              value={form.username}
              onChange={handleChange}
              className="w-full rounded-xl border border-slate-200 px-4 py-3 outline-none"
            />
          </div>

          {/* PASSWORD */}

          <div>
            <label className="mb-2 block text-sm font-semibold text-slate-700">
              Password
            </label>

            <input
              type="password"
              name="password"
              value={form.password}
              onChange={handleChange}
              className="w-full rounded-xl border border-slate-200 px-4 py-3 outline-none"
            />
          </div>

          {/* ROLE */}

          <div>
            <label className="mb-2 block text-sm font-semibold text-slate-700">
              Role
            </label>

            <select
              name="role"
              value={form.role}
              onChange={handleChange}
              className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none"
            >
              <option value="USER">
                USER
              </option>

              <option value="HOSPITAL">
                HOSPITAL
              </option>

              <option value="GOVERNMENT OFFICE">
                GOVERNMENT OFFICE
              </option>

              <option value="ADMIN">
                ADMIN
              </option>
            </select>
          </div>

          {/* ERROR */}

          {error && (
            <div className="rounded-xl bg-red-50 p-3 text-sm font-medium text-red-700">
              {error}
            </div>
          )}

          {/* LOGIN BUTTON */}

          <button
            type="submit"
            disabled={loading}
            className="w-full rounded-xl bg-blue-700 py-3 font-semibold text-white"
          >
            {loading
              ? "Signing in..."
              : "Login"}
          </button>

        </form>

      </div>

    </main>
  );
}

export default LoginPage;
